window.RP_SESSION={"id":"S-fc7128450dae","messages":[{"id":"RP-III-0067046","time":"2026-04-05T22:54:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"비가 무척 세게 내립니다. 큰 소리와 밝은 빛이 지속적으로 교차하자···. 계속 움찔거리며 소리 맞이하던 레아는 덮어쓰던 이불을 내리고, 터덜터덜 길드 회관으로 향합니다.","characters":["P-92b9d287989c"]},{"id":"RP-III-0067047","time":"2026-04-05T22:59:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"식은땀 좀 닦아내고···. 아침에 잠시 나가 사왔던 티라미수 꺼냅니다.","characters":["P-92b9d287989c"]},{"id":"RP-III-0067048","time":"2026-04-05T23:00:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"천둥 칠때마다 지속적으로 움찔거리며 창 밖을 바라보다가. 끙 소리내며 결국 손으로 귀를 틀어막습니다.","characters":["P-92b9d287989c"]},{"id":"RP-III-0067049","time":"2026-04-05T23:02:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"티라미수 살짝 밀어놓고, 고개 푹 숙이고 있습니다.","characters":["P-92b9d287989c"]},{"id":"RP-III-0067050","time":"2026-04-05T23:03:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"여전히 천둥 소리는 무섭습니다.","characters":["P-92b9d287989c"]},{"id":"RP-III-0067051","time":"2026-04-05T23:15:00+09:00","room":"RP III","name":"레아","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-92b9d287989c"]},{"id":"RP-III-0067052","time":"2026-04-05T23:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
